from itertools import product
D=[([(0,0),(0,11),(1,4),(2,7),(5,15)],[(3,1),(4,10),(5,6)]), ([(0,12),(4,3),(4,7)],[(1,1),(1,4),(2,9)]), ([(1,13),(3,8),(4,5),(5,0)],[(0,6),(2,2),(5,11)])]
S=[x for a,b in D for x in a]; U=[x for a,b in D for x in b]
print('totals',len(S),len(U))
# Linear integer threshold, modular single residue exact separation
hits=[]
for m in range(2,16):
 for a,b in product(range(m),repeat=2):
  ss={(a*r+b*c)%m for r,c in S}; uu={(a*r+b*c)%m for r,c in U}
  if not ss&uu: hits.append((m,a,b,sorted(ss),sorted(uu)))
print('modular clean',hits[:30], 'count',len(hits))
# linear scores ranges separation
for a,b in product(range(-5,6),repeat=2):
 if (a,b)==(0,0): continue
 ss=[a*r+b*c for r,c in S]; uu=[a*r+b*c for r,c in U]
 if max(uu)<min(ss) or max(ss)<min(uu): print('linear sep',a,b,min(ss),max(ss),min(uu),max(uu))

