  for b in range(-10,11):
   vals=[(a*r+b*c)%m for r,c,y in pts]
   for k in range(m):
    pred=[v==k for v in vals]
    if pred==[bool(y) for r,c,y in pts]: sol.append((m,a,b,k))
print('exact single residue',sol[:20],len(sol))
# linear threshold in a*r+b*c with coefficients small, selected side or interval
from collections import Counter
