for a in range(-8,9):
 for b in range(-8,9):
  vs=[a*r+b*c for r,c,y in pts]
  ys=[y for r,c,y in pts]
  for t in sorted(set(vs)):
   acc=sum((v>=t)==bool(y) for v,y in zip(vs,ys))
