 "tasks": [
  {
   "goal": "Try novel hypothesis: select objects that are at higher/lower row or col edge, or connected to two others; return exact subset",
   "context": "All statuses listed in parent context; output test subset.",
   "role": "leaf",
   "output_schema": {}
  },
  {
   "goal": "Try infer relation from diagonals / row-column alignment; best prediction",
   "context": "All statuses listed in parent context.",
   "role": "leaf",
   "output_schema": {}
  }
 ],
 "role": "orchestrator",
 "output_schema": {},
 "background": true,
 "action": "spawn",
 "subagent_id": "",
 "message": ""
}

demos=[([(0,0),(0,11),(1,4),(2,7),(5,15)],[(3,1),(4,10),(5,6)]), ([(0,12),(4,3),(4,7)],[(1,1),(1,4),(2,9)]), ([(1,13),(3,8),(4,5),(5,0)],[(0,6),(2,2),(5,11)]), ([(1,5),(2,0),(2,5)],[(4,2)]), ([(4,3)],[(1,0)])]
items=[(r,c,1) for s,u in demos for r,c in s]+[(r,c,0) for s,u in demos for r,c in u]
from collections import defaultdict
features={
 'r':lambda r,c:r,'c':lambda r,c:c,'r+c':lambda r,c:r+c,'r-c':lambda r,c:r-c,'r*c':lambda r,c:r*c,
 'r%2':lambda r,c:r%2,'c%2':lambda r,c:c%2,'sum%2':lambda r,c:(r+c)%2,'diff%2':lambda r,c:(r-c)%2,
 'sum%3':lambda r,c:(r+c)%3,'diff%3':lambda r,c:(r-c)%3,'c%3':lambda r,c:c%3,'r%3':lambda r,c:r%3,
 'c%4':lambda r,c:c%4,'sum%4':lambda r,c:(r+c)%4,'diff%4':lambda r,c:(r-c)%4,
}
for name,f in features.items():
 vals=defaultdict(set)
 for r,c,y in items: vals[f(r,c)].add(y)
 pure={k:next(iter(v)) for k,v in vals.items() if len(v)==1}
 acc=sum((f(r,c) in pure and pure[f(r,c)]==y) for r,c,y in items)
 if acc>=len(items)-2: print(name,acc,'/',len(items),dict(pure))
# exact summarize feature correlations
for name,f in features.items():
 vals=defaultdict(lambda:[0,0])
 for r,c,y in items: vals[f(r,c)][y]+=1
 print(name,dict(vals))

